SELECT 'batch_005_44608fa2_wav_07' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-079b5a30-681','sm-upload-11bfd8b6-551','sm-upload-22d36802-2ad','sm-upload-3e173d57-c25','sm-upload-604ea1ac-255','sm-upload-605d34a4-800','sm-upload-cdea3d45-1a9') AND album_id='al-1ec1e919cdf08d8aa1af5dc344608fa2') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-079b5a30-681','sm-upload-11bfd8b6-551','sm-upload-22d36802-2ad','sm-upload-3e173d57-c25','sm-upload-604ea1ac-255','sm-upload-605d34a4-800','sm-upload-cdea3d45-1a9') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-1ec1e919cdf08d8aa1af5dc344608fa2' AND name='被那个夏天厌恶的我们') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-1ec1e919cdf08d8aa1af5dc344608fa2') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-1ec1e919cdf08d8aa1af5dc344608fa2') AS calculated_size;
